import { CurrentPrice } from '@cetus/design'
import { CoinInfo } from '@cetus/types'
import { Icon } from '@cetus/ui-kit'
import { formatPercentage } from '@cetus/utils'
import { d } from '@cetusprotocol/cetus-sui-clmm-sdk'
import { HStack, Text, Tooltip, VStack } from '@chakra-ui/react'

type PriceImpactProps = {
  fromToken: CoinInfo
  toToken: CoinInfo
  marketPrice?: string
  priceImpact?: string
  sources: string[]
}

export default function PriceImpact(props: PriceImpactProps) {
  const { fromToken, toToken, marketPrice, priceImpact, sources } = props

  return (
    <HStack w="100%" justifyContent="space-between">
      <HStack alignItems="end">
        <Text fontSize="14px">Price Impact</Text>
        <Tooltip label={<PriceImpactTips marketPrice={marketPrice} sources={sources} fromToken={fromToken} toToken={toToken} />} aria-label="Yield">
          <button>
            <Icon xlinkHref="#icon-icon_tips" svgW="20px" svgH="20px" />
          </button>
        </Tooltip>
      </HStack>
      <HStack>
        <Text color={priceImpact && d(priceImpact).gt(0) ? 'primary_green' : 'primary_red'}>{formatPercentage(priceImpact)}</Text>
      </HStack>
    </HStack>
  )
}

type PriceImpactTipsProps = {
  fromToken: CoinInfo
  toToken: CoinInfo
  marketPrice?: string
  sources: string[]
}

function PriceImpactTips(props: PriceImpactTipsProps) {
  const { marketPrice, sources, fromToken, toToken } = props
  return (
    <VStack w="100%" alignItems="start">
      <Text color="content_text" fontSize="14px">
        The difference between the market price and estimated price due to trade size.
      </Text>

      <Text fontSize="14px">Market price sources:</Text>

      <CurrentPrice fontSize="14px" fromToken={fromToken!} toToken={toToken!} fromValue="1" toValue={marketPrice} />

      <Text color="content_text" fontSize="14px" mt="5px" whiteSpace="pre">
        {`Market price sources:    ${sources.map(item => item + '  ')}`}
      </Text>
    </VStack>
  )
}
