import { usePriceImpact } from '@/hooks/swap/usePriceImpact'
import { useGetAmountLimit, useGetPriceAcceptRouterData } from '@/hooks/swap/useSwapHelper'
import useSwapStore from '@/store/swap/swap'
import useSwapConfigStore from '@/store/swap/swapConfig'
import { SwapRouterData } from '@/types/swap'
import { CurrentPrice, TradeConfirmAmountInfo } from '@cetus/design'
import { HTextLabelBox, Icon } from '@cetus/ui-kit'
import { formatNumber } from '@cetus/utils'
import { d } from '@cetusprotocol/cetus-sui-clmm-sdk'
import { Button, HStack, Heading, Modal, ModalBody, ModalCloseButton, ModalContent, ModalHeader, ModalOverlay, Text, VStack } from '@chakra-ui/react'
import { useMemo, useState } from 'react'
import PriceImpact from '../swap/PriceImpact'

type SwapConfirmModelProps = {
  data: SwapRouterData
  isOpen: boolean
  onClose: () => void
}

export default function SwapConfirmModel(props: SwapConfirmModelProps) {
  const { isOpen, onClose, data } = props
  const { fromCoin, toCoin } = useSwapStore()

  const { slippage } = useSwapConfigStore()
  const [originData, setOriginData] = useState<SwapRouterData>(data)
  const { amountLimit } = useGetAmountLimit(slippage, originData)
  const { fromAmountUi, toAmountUi, byAmountIn } = originData

  const { priceImpact, marketPrice, sources } = usePriceImpact(fromCoin, toCoin, fromAmountUi, toAmountUi)
  const { priceAcceptRouterData } = useGetPriceAcceptRouterData(originData)

  const onPriceImpactChange = (priceImpact: string) => {
    if (priceImpact && +priceImpact) {
      //  setShowPriceImpactTips(d(priceImpact).abs().gte(10))
    } else {
      //  setShowPriceImpactTips(false)
    }
  }

  const fixCoin = useMemo(() => {
    return byAmountIn ? fromCoin : toCoin
  }, [byAmountIn])

  const showPriceUpdated = useMemo(() => {
    return priceAcceptRouterData !== undefined
  }, [priceAcceptRouterData])

  const handlePriceAcceptClick = () => {
    if (priceAcceptRouterData) {
      setOriginData({ ...priceAcceptRouterData })
    }
  }

  return (
    <Modal isOpen={isOpen} onClose={onClose}>
      <ModalOverlay />
      <ModalContent>
        <ModalHeader>
          <Heading fontWeight="500" fontSize="16px">
            Swap
          </Heading>
        </ModalHeader>
        <ModalCloseButton />
        <ModalBody textAlign="center" p="0px">
          <VStack w="100%" gap="16px" p="16px">
            {/* 交易数量展示 */}
            <TradeConfirmAmountInfo
              coinA={{
                amount: fromAmountUi,
                logo: fromCoin?.logo_url || '',
                symbol: fromCoin?.symbol
              }}
              icon="#icon-a-icon_trade"
              coinB={{
                amount: toAmountUi,
                logo: toCoin?.logo_url || '',
                symbol: toCoin?.symbol
              }}
            />
            {/* 价格 */}
            <HStack w="100%" minH="48px" bg="bg_primary" borderRadius="8px" border="1px solid" borderColor="border" justifyContent="center">
              <CurrentPrice fromToken={fromCoin!} toToken={toCoin!} fromValue={fromAmountUi} toValue={toAmountUi} />
            </HStack>
            <HTextLabelBox
              leftLabel={'Slippage Tolerance'}
              leftLabelFontSize="14px"
              rightValue={`${d(slippage).mul(100)}%`}
              rightValueFontSize="14px"
            />
            <HTextLabelBox
              leftLabel={byAmountIn ? 'Minimum Received' : 'Maximum Input'}
              leftLabelFontSize="14px"
              rightValue={`${formatNumber(amountLimit || 0, fixCoin?.decimals).toString()} ${fixCoin?.symbol}`}
              rightValueFontSize="14px"
            />

            <PriceImpact fromToken={fromCoin!} toToken={toCoin!} sources={sources} marketPrice={marketPrice} priceImpact={priceImpact} />

            {showPriceUpdated && (
              <HStack w="100%" justifyContent="space-between">
                <HStack>
                  <Icon xlinkHref="#icon-icon_priceupdated1" svgW="20px" svgH="20px" />
                  <Text>Price updated</Text>
                </HStack>
                <Button onClick={handlePriceAcceptClick}>Accept</Button>
              </HStack>
            )}
          </VStack>
          {!showPriceUpdated && (
            <Button mt="4px" w="100%">
              Confirm Swap
            </Button>
          )}
        </ModalBody>
      </ModalContent>
    </Modal>
  )
}
