import useSwapStore from '@/store/swap/swap'
import { useAccountStore } from '@cetus/stores'
import { d } from '@cetusprotocol/cetus-sui-clmm-sdk'
import { useMemo } from 'react'

export function useSwapButtonStatus(fromBalance?: string) {
  const { fromCoin, fromAmount, toAmount } = useSwapStore()
  const { currentAccount } = useAccountStore()

  const submitBtnInfo = useMemo(() => {
    const btnInfo: {
      text?: string
      disabled: boolean
    } = {
      text: 'Swap',
      disabled: false
    }

    // 判断钱包
    if (!currentAccount?.address) {
      btnInfo.text = 'Connect Wallet'
      btnInfo.disabled = false
      return btnInfo
    }

    // 判断输入
    if (!+fromAmount && !+toAmount) {
      btnInfo.text = 'Enter an amount'
      btnInfo.disabled = true
      return btnInfo
    }

    //判断余额
    if (+fromAmount && d(fromAmount).gt(fromBalance || 0)) {
      btnInfo.disabled = true
      btnInfo.text = `Insufficient ${fromCoin?.symbol} Balance`
      return btnInfo
    }

    if (!+fromAmount || !+toAmount) {
      btnInfo.disabled = true
      return btnInfo
    }

    return btnInfo
  }, [currentAccount?.address, fromAmount, toAmount, fromBalance])

  return {
    btnText: submitBtnInfo.text,
    btnDisabled: submitBtnInfo.disabled
  }
}
