import { SwapTabs, SwapTrade } from '@/components/swap'
import { SelectTab } from '@cetus/design'
import { Tab } from '@cetus/design/src/components/common/SelectTab'
import { Box, HStack, VStack } from '@chakra-ui/react'
import { useState } from 'react'

const swapTabList = [
  {
    label: SwapTabs.Swap
  },
  {
    label: SwapTabs.Limit
  },
  {
    label: SwapTabs.DCA,
    beta: true
  }
]

const TradeMap = {
  [SwapTabs.Swap]: SwapTrade,
  [SwapTabs.Limit]: 'limit',
  [SwapTabs.DCA]: 'dca'
}

function Swap() {
  const [tab, setTab] = useState(SwapTabs.Swap)
  const Trade = TradeMap[tab]
  return (
    <Box>
      <HStack>
        {tab !== SwapTabs.Swap && <Box>chart</Box>}
        <VStack>
          <HStack w="100%" justify="space-between">
            <SelectTab
              type="borderTab"
              currentTab={tab}
              tabList={swapTabList}
              handleChangeTab={tab => setTab((tab as Tab)?.label as SwapTabs)}
              wrapStyle={{
                bg: 'background',
                h: '52px',
                gap: '32px',
                border: 'none'
              }}
              itemStyle={{
                fontSize: '16px',
                fontWeight: 500
              }}
            />
            {tab !== SwapTabs.Swap && <HStack>icon</HStack>}
          </HStack>
          <Box>
            <Trade />
          </Box>
        </VStack>
      </HStack>
      {tab === SwapTabs.Limit && <Box>table</Box>}
    </Box>
  )
}

export default Swap
